import Foundation
import NIO
import NIOHTTP1

// ML Inference Server - handles concurrent model inference requests
final class InferenceServer {
    private let group: MultiThreadedEventLoopGroup
    private let modelCache: ModelCache
    private let uploadDir: String
    private let maxConcurrent: Int = 8

    init(threads: Int = 4) {
        self.group = MultiThreadedEventLoopGroup(numberOfThreads: threads)
        self.modelCache = ModelCache()
        self.uploadDir = "/tmp/ml_uploads"
        try? FileManager.default.createDirectory(atPath: uploadDir, withIntermediateDirectories: true)
    }

    func processUpload(userId: String, data: Data, completion: @escaping (Result<InferenceResult, Error>) -> Void) {
        let requestId = UUID().uuidString
        let sanitizedUserId = userId.replacingOccurrences(of: "..", with: "").replacingOccurrences(of: "/", with: "_")
        let workPath = "\(uploadDir)/\(sanitizedUserId)_\(requestId)"

        // Phase 1: Validate and write upload
        guard validatePayload(data: data) else {
            completion(.failure(InferenceError.invalidPayload))
            return
        }

        do {
            try data.write(to: URL(fileURLWithPath: workPath))
        } catch {
            completion(.failure(error))
            return
        }

        // Phase 2: Load model and run inference
        let session = InferenceSession(requestId: requestId, workPath: workPath, userId: sanitizedUserId)
        modelCache.acquireModel(for: session) { [weak self] result in
            switch result {
            case .success(let model):
                self?.runInference(session: session, model: model, completion: completion)
            case .failure(let error):
                self?.cleanup(session: session)
                completion(.failure(error))
            }
        }
    }

    private func runInference(session: InferenceSession, model: MLModel, completion: @escaping (Result<InferenceResult, Error>) -> Void) {
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            guard let self = self else { return }

            do {
                let inputData = try Data(contentsOf: URL(fileURLWithPath: session.workPath))
                let tensor = try self.preprocessInput(data: inputData, model: model)
                let output = try model.predict(input: tensor)
                let result = InferenceResult(requestId: session.requestId, predictions: output, confidence: model.lastConfidence)
                self.cleanup(session: session)
                completion(.success(result))
            } catch {
                self.cleanup(session: session)
                completion(.failure(error))
            }
        }
    }

    private func cleanup(session: InferenceSession) {
        try? FileManager.default.removeItem(atPath: session.workPath)
        modelCache.releaseModel(for: session)
    }

    private func validatePayload(data: Data) -> Bool {
        guard data.count > 16 && data.count < 10_000_000 else { return false }
        // Check magic bytes for supported formats
        let header = data.prefix(4)
        let validHeaders: [Data] = [
            Data([0x89, 0x50, 0x4E, 0x47]), // PNG
            Data([0xFF, 0xD8, 0xFF, 0xE0]), // JPEG
            Data([0x00, 0x00, 0x00, 0x1C])  // Custom tensor format
        ]
        return validHeaders.contains(where: { header.starts(with: $0) })
    }

    private func preprocessInput(data: Data, model: MLModel) throws -> Tensor {
        return try Tensor(fromRawData: data, shape: model.inputShape)
    }
}

// Model cache with reference counting
final class ModelCache {
    private var models: [String: MLModel] = [:]
    private var refCounts: [String: Int] = [:]
    private let lock = NSLock()
    private var sessionModelMap: [String: String] = [:]

    func acquireModel(for session: InferenceSession, completion: @escaping (Result<MLModel, Error>) -> Void) {
        let modelKey = resolveModelKey(for: session)

        lock.lock()
        sessionModelMap[session.requestId] = modelKey

        if let model = models[modelKey] {
            refCounts[modelKey, default: 0] += 1
            lock.unlock()
            completion(.success(model))
        } else {
            lock.unlock()
            // Load model asynchronously
            loadModel(key: modelKey) { [weak self] result in
                guard let self = self else { return }
                switch result {
                case .success(let model):
                    self.lock.lock()
                    self.models[modelKey] = model
                    self.refCounts[modelKey, default: 0] += 1
                    self.lock.unlock()
                    completion(.success(model))
                case .failure(let error):
                    completion(.failure(error))
                }
            }
        }
    }

    func releaseModel(for session: InferenceSession) {
        lock.lock()
        guard let modelKey = sessionModelMap.removeValue(forKey: session.requestId) else {
            lock.unlock()
            return
        }
        refCounts[modelKey, default: 1] -= 1
        if refCounts[modelKey, default: 0] <= 0 {
            // Evict model when no references remain
            models.removeValue(forKey: modelKey)
            refCounts.removeValue(forKey: modelKey)
        }
        lock.unlock()
    }

    private func resolveModelKey(for session: InferenceSession) -> String {
        return "default_v2"
    }

    private func loadModel(key: String, completion: @escaping (Result<MLModel, Error>) -> Void) {
        DispatchQueue.global().async {
            do {
                let model = try MLModel(name: key)
                completion(.success(model))
            } catch {
                completion(.failure(error))
            }
        }
    }
}

struct InferenceSession {
    let requestId: String
    let workPath: String
    let userId: String
}

struct InferenceResult {
    let requestId: String
    let predictions: [Float]
    let confidence: Float
}

enum InferenceError: Error {
    case invalidPayload
    case modelNotFound
    case preprocessingFailed
}

// Stub types for compilation context
class MLModel {
    let inputShape: [Int]
    var lastConfidence: Float = 0.0
    init(name: String) throws { self.inputShape = [1, 224, 224, 3] }
    func predict(input: Tensor) throws -> [Float] { return [0.95, 0.03, 0.02] }
}

struct Tensor {
    init(fromRawData data: Data, shape: [Int]) throws {}
